import{_ as t,a0 as o,w as d,s as r,ao as p,I as a,x as n,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux 内核动手编译实用指南 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 内核动手编译实用指南 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 内核动手编译实用指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 内核动手编译实用指南 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231002 A Guide to Compiling the Linux Kernel All By Yourself","title":"Linux 内核动手编译实用指南","tag":"202310","desc":""},"relativePath":"202310/20231002 A Guide to Compiling the Linux Kernel All By Yourself.md","filePath":"[post].md"}'),c={name:"202310/20231002 A Guide to Compiling the Linux Kernel All By Yourself.md"};function g(u,s,h,k,b,f){const i=o("Link");return d(),r("div",null,[s[54]||(s[54]=p('<h1 id="linux-内核动手编译实用指南" tabindex="-1">Linux 内核动手编译实用指南 <a class="header-anchor" href="#linux-内核动手编译实用指南" aria-label="Permalink to “Linux 内核动手编译实用指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/04/115142ggqqhuclvxdxsb14.jpg" alt=""></p><blockquote><p>一份让你深入体验最新 Linux 内核编译过程的实操指南。</p></blockquote><p>出于各种原因，自行编译 Linux 内核可能引起你的兴趣。这些原因可能包括但不限于：</p><ul><li>测试一个比你目前的 Linux 发行版更新的内核版本</li><li>采用一组不同的配置选项、驱动来构建内核</li><li>学习者的好奇心 😃</li></ul><p>此指南将一步步指导你如何亲自编译 Linux 内核，包括你该运行哪些命令，为什么运行这些命令以及这些命令的执行效果。本文篇幅较长，所以请做好准备！</p>',6)),a("blockquote",null,[a("p",null,[s[1]||(s[1]=n("🚧 诸如 ",-1)),e(i,{href:"https://itsfoss.com/upgrade-linux-kernel-ubuntu/"},{default:l(()=>[...s[0]||(s[0]=[n("Ubuntu 这样的发行版提供了更简单地安装主线 Linux 内核的方式",-1)])]),_:1}),s[2]||(s[2]=n("。但本教程目标是从源码手动完成所有工作。",-1)),s[3]||(s[3]=a("strong",null,"此教程需要你付出时间、耐心以及丰富的 Linux 命令行使用经验",-1)),s[4]||(s[4]=n("。本文更注重亲身实践的体验。不管怎么说，我仍建议你在虚拟机或备用系统中尝试此冒险，而非在你的主系统上进行。",-1))])]),s[55]||(s[55]=a("h3",{id:"前置准备",tabindex:"-1"},[n("前置准备 "),a("a",{class:"header-anchor",href:"#前置准备","aria-label":"Permalink to “前置准备”"},"​")],-1)),s[56]||(s[56]=a("p",null,"在软件领域，构建任何事物都有两个基本要求：",-1)),s[57]||(s[57]=a("ol",null,[a("li",null,"源代码"),a("li",null,"构建依赖")],-1)),s[58]||(s[58]=a("p",null,"因此，作为预备环节，我们需要下载 Linux 内核的源码压缩包，并安装一些能让我们成功构建 Linux 内核的依赖项。",-1)),s[59]||(s[59]=a("h4",{id:"linux-版本导览",tabindex:"-1"},[n("Linux 版本导览 "),a("a",{class:"header-anchor",href:"#linux-版本导览","aria-label":"Permalink to “Linux 版本导览”"},"​")],-1)),a("p",null,[s[6]||(s[6]=n("在任何时刻，",-1)),e(i,{href:"https://en.wikipedia.org/wiki/History_of_Linux#Naming"},{default:l(()=>[...s[5]||(s[5]=[a("s",null,"Freax",-1)])]),_:1}),s[7]||(s[7]=n(" Linux 内核都有四种“版本”。",-1))]),s[60]||(s[60]=a("p",null,"Linux 的这些 “版本”，按照开发流程的顺序是：",-1)),a("ol",null,[s[14]||(s[14]=p("<li><strong>linux-next 树：</strong> 所有准备合并到 Linux 代码库的代码首先被合并到 linux-next 树。它代表的是 Linux 内核最新也是“最不稳定”的状态。大多数 Linux 内核开发者和测试人员使用这个来提高代码质量，为 Linus Torvalds 的后续提取做准备。<strong>请谨慎使用！</strong></li><li><strong>发布候选版（RC） / 主线版：</strong> Linus 从 linux-next 树抽取代码并创建一个初始发布版本。这个初始发布版本的测试版称为 RC（<ruby>发布候选<rt>Release Candidate</rt></ruby>）版本。一旦 RC 版本发布，Linus 只会接受对它的错误修复和性能退化相关的补丁。基础这些反馈，Linus 会每周发布一个 RC 内核，直到他对代码感到满意。RC 发行版本的标识是 <code>-rc</code> 后缀，后面跟一个数字。</li><li><strong>稳定版：</strong> 当 Linus 觉得最新的 RC 版本已稳定时，他会发布最终的“公开”版本。稳定发布版将会维护几周时间。像 Arch Linux 和 Fedora Linux 这样的前沿 Linux 发行版会使用此类版本。<strong>我建议你在试用 linux-next 或任何 RC 版本之前，先试一试此版本。</strong></li>",3)),a("li",null,[s[9]||(s[9]=a("strong",null,"LTS 版本：",-1)),s[10]||(s[10]=n(" 每年最后一个稳定版将会再维护 ",-1)),e(i,{href:"https://news.itsfoss.com/linux-kernel-support/"},{default:l(()=>[...s[8]||(s[8]=[n("几年",-1)])]),_:1}),s[11]||(s[11]=n("。这通常是一个较旧的版本，但它会 ",-1)),s[12]||(s[12]=a("strong",null,"会积极地维护并提供安全修复",-1)),s[13]||(s[13]=n("。Debian 的稳定版本会使用 Linux 内核的 LTS 版版本。",-1))])]),a("p",null,[s[16]||(s[16]=n("若想了解更多此方面的知识，可参阅 ",-1)),e(i,{href:"https://www.kernel.org/category/releases.html"},{default:l(()=>[...s[15]||(s[15]=[n("官方文档",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),a("p",null,[s[19]||(s[19]=n("本文将以当前可用的最新稳定版为例，编写此文时的 Linux 内核版本是 ",-1)),e(i,{href:"https://lwn.net/Articles/945378/"},{default:l(()=>[...s[18]||(s[18]=[n("6.5.5",-1)])]),_:1}),s[20]||(s[20]=n("。",-1))]),s[61]||(s[61]=p(`<h3 id="系统准备" tabindex="-1">系统准备 <a class="header-anchor" href="#系统准备" aria-label="Permalink to “系统准备”">​</a></h3><p>由于 Linux 内核使用 C 语言编写，编译 Linux 内核至少需要一个 C 编译器。你的计算机上可能还需要其他一些依赖项，现在是安装它们的时候了。</p><blockquote><p>💡 这个指南主要聚焦于使用 GNU C 编译器（GCC）来编译 Linux 内核。但在未来的文章中（可能会深入介绍 Rust 的支持），我<strong>可能</strong>会介绍使用 LLVM 的 Clang 编译器作为 GCC 的替代品。</p><p>不过，请注意，MSVC 并不适用。尽管如此，我仍期待有微软的员工为此发送修补程序集。我在瞎想啥？</p></blockquote><p>对于 Arch Linux 以及其衍生版本的用户，安装命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S base-devel bc coreutils cpio gettext initramfs kmod libelf ncurses pahole perl python rsync tar xz</span></span></code></pre></div><p>对于 Debian 以及其衍生版本的用户，安装命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install bc binutils bison dwarves flex gcc git gnupg2 gzip libelf-dev libncurses5-dev libssl-dev make openssl pahole perl-base rsync tar xz-utils</span></span></code></pre></div><p>对于 Fedora 以及其衍生版本的用户，安装命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install binutils ncurses-devel \\</span></span>
<span class="line"><span>    /usr/include/{libelf.h,openssl/pkcs7.h} \\</span></span>
<span class="line"><span>    /usr/bin/{bc,bison,flex,gcc,git,gpg2,gzip,make,openssl,pahole,perl,rsync,tar,xz,zstd}</span></span></code></pre></div><h4 id="下载-linux-内核源码" tabindex="-1">下载 Linux 内核源码 <a class="header-anchor" href="#下载-linux-内核源码" aria-label="Permalink to “下载 Linux 内核源码”">​</a></h4>`,10)),a("p",null,[s[22]||(s[22]=n("请访问 ",-1)),e(i,{href:"https://kernel.org/"},{default:l(()=>[...s[21]||(s[21]=[n("kernel.org",-1)])]),_:1}),s[23]||(s[23]=n("，在页面中寻找第一个 ",-1)),s[24]||(s[24]=a("ruby",null,[n("稳定"),a("rt",null,"Stable")],-1)),s[25]||(s[25]=n(" 版本。你不会找不到它，因为它是最显眼的黄色方框哦 😉",-1))]),a("blockquote",null,[a("p",null,[a("strong",null,[e(i,{href:"https://kernel.org/"},{default:l(()=>[...s[26]||(s[26]=[n("点击访问 kernel.org",-1)])]),_:1})])])]),s[62]||(s[62]=p(`<p><img src="https://itsfoss.com/content/images/2023/09/Screenshot-2023-09-24-at-2.21.00-PM.png" alt=""></p><p>通过点击黄色的方框，你就可以下载 Tar 文件。同时，也别忘了下载相匹配的 PGP 签名文件，稍后我们需要用到它来验证 Tar 文件。它的扩展名为 <code>.tar.sign</code>。</p><h5 id="校验-tar-文件的完整性" tabindex="-1">校验 Tar 文件的完整性 <a class="header-anchor" href="#校验-tar-文件的完整性" aria-label="Permalink to “校验 Tar 文件的完整性”">​</a></h5><p>你如何知道刚下载的 Tar 文件是否被损坏？对于个人来说，一个损坏的 Tar 文件只会浪费你的宝贵时间，如果你是在为一个组织工作，那么可能会危及到组织的安全（这时你可能还有更大的问题需要担忧，但我们并不想让所有人都产生创伤后应激障碍！）。</p><p>为了验证我们的 Tar 文件的完整性，我们需要先解压它。目前，它是使用 XZ 压缩算法压缩的。因此，我将使用 <code>unxz</code> 工具（其实就是 <code>xz --decompress</code> 的别名）来解压 <code>.tar.xz</code> 格式的压缩文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unxz --keep linux-*.tar.xz</span></span></code></pre></div><p>解压完成后，我们需要获取 Linus Torvalds 和 Greg KH 使用的 GPG 公开密钥。这些密钥用于对 Tar 文件进行签名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg2 --locate-keys torvalds@kernel.org gregkh@kernel.org</span></span></code></pre></div><p>你应该可以得到一个与我在我的电脑上看到的类似的结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg2 --locate-keys torvalds@kernel.org gregkh@kernel.org</span></span>
<span class="line"><span>gpg: /home/pratham/.gnupg/trustdb.gpg: trustdb created</span></span>
<span class="line"><span>gpg: key 38DBBDC86092693E: public key &quot;Greg Kroah-Hartman &lt;gregkh@kernel.org&gt;&quot; imported</span></span>
<span class="line"><span>gpg: Total number processed: 1</span></span>
<span class="line"><span>gpg:               imported: 1</span></span>
<span class="line"><span>gpg: key 79BE3E4300411886: public key &quot;Linus Torvalds &lt;torvalds@kernel.org&gt;&quot; imported</span></span>
<span class="line"><span>gpg: Total number processed: 1</span></span>
<span class="line"><span>gpg:               imported: 1</span></span>
<span class="line"><span>pub   rsa4096 2011-09-23 [SC]</span></span>
<span class="line"><span>      647F28654894E3BD457199BE38DBBDC86092693E</span></span>
<span class="line"><span>uid           [ unknown] Greg Kroah-Hartman &lt;gregkh@kernel.org&gt;</span></span>
<span class="line"><span>sub   rsa4096 2011-09-23 [E]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pub   rsa2048 2011-09-20 [SC]</span></span>
<span class="line"><span>      ABAF11C65A2970B130ABE3C479BE3E4300411886</span></span>
<span class="line"><span>uid           [ unknown] Linus Torvalds &lt;torvalds@kernel.org&gt;</span></span>
<span class="line"><span>sub   rsa2048 2011-09-20 [E]</span></span></code></pre></div><p>在导入 Greg 和 Linus 的密钥后，我们可以使用 <code>--verify</code> 标志来验证 Tar 的完整性，操作如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg2 --verify linux-*.tar.sign</span></span></code></pre></div><p>如果验证成功，你应该会看到如下的输出信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg2 --verify linux-*.tar.sign</span></span>
<span class="line"><span>gpg: assuming signed data in &#39;linux-6.5.5.tar&#39;</span></span>
<span class="line"><span>gpg: Signature made Saturday 23 September 2023 02:46:13 PM IST</span></span>
<span class="line"><span>gpg:                using RSA key 647F28654894E3BD457199BE38DBBDC86092693E</span></span>
<span class="line"><span>gpg: Good signature from &quot;Greg Kroah-Hartman &lt;gregkh@kernel.org&gt;&quot; [unknown]</span></span>
<span class="line"><span>gpg: WARNING: This key is not certified with a trusted signature!</span></span>
<span class="line"><span>gpg:          There is no indication that the signature belongs to the owner.</span></span>
<span class="line"><span>Primary key fingerprint: 647F 2865 4894 E3BD 4571  99BE 38DB BDC8 6092 693E</span></span></code></pre></div><p><strong>务必查看是否存在 <code>gpg: Good signature</code> 的提示，然后再继续！</strong></p><blockquote><p>💡 你可以忽略以下警告：<code>WARNING: This key is not certified with a trusted signature! There is no indication that the signature belongs to the owner.</code>。</p><p>我们已根据 Linus 和 Greg 的邮件地址获取了公开密钥，并无需对此警告感到担忧。</p></blockquote><h5 id="解压-tar-文件" tabindex="-1">解压 Tar 文件 <a class="header-anchor" href="#解压-tar-文件" aria-label="Permalink to “解压 Tar 文件”">​</a></h5><p>如果你顺利的进行到这里，意味着你的 Tar 文件完整性检查已经成功完成。接下来，我们将从 Tar 文件中解压出 Linux 内核的源码。</p><p><img src="https://itsfoss.com/content/images/2023/09/tar_2x.png" alt="The &quot;TAR&quot; xkcd comic: https://xkcd.com/1168/"></p><p>这个步骤十分简单，只需对 Tar 文件执行 <code>tar -xf</code> 命令，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tar -xf linux-*.tar</span></span></code></pre></div><p>在这里，<code>-x</code> 选项表示解压，<code>-f</code> 选项则用来告诉 Tar 文件的文件名。</p><p>这个解压过程可能需要几分钟时间，你可以先放松，耐心等待一下。</p><h3 id="配置-linux-内核" tabindex="-1">配置 Linux 内核 <a class="header-anchor" href="#配置-linux-内核" aria-label="Permalink to “配置 Linux 内核”">​</a></h3><p>Linux 内核的构建过程会查找 <code>.config</code> 文件。顾名思义，这是一个配置文件，用于指定 Linux 内核的所有可能的配置选项。这是必需的文件。</p><p>获取 Linux 内核的 <code>.config</code> 文件有两种方式：</p><ol><li>使用你的 Linux 发行版的配置作为基础（<strong>推荐做法</strong>）</li><li>使用默认的，通用的配置</li></ol><blockquote><p>💡 也有第三种方法，也就是从零开始，手动配置每一个选项，但注意，这需要配置超过 12,000 个选项。并不推荐这种方式，因为手动配置所有选项将花费大量的时间，并且你还需要理解每个启用和禁用选项的含义。</p></blockquote><h4 id="使用发行版提供的配置" tabindex="-1">使用发行版提供的配置 <a class="header-anchor" href="#使用发行版提供的配置" aria-label="Permalink to “使用发行版提供的配置”">​</a></h4><p><strong>使用你的 Linux 发行版提供的配置是一个安全的选择。</strong> 如果你只是跟随这个指南测试一个不是你的发行版提供的新内核，那么这就是推荐的方式。</p><p>你的 Linux 发行版的 Linux 内核配置文件会在以下两个位置之一：</p><ul><li>大多数 Linux 发行版，如 Debian 和 Fedora 及其衍生版，将会把它存在 <code>/boot/config-$(uname -r)</code>。</li><li>一些 Linux 发行版，比如 Arch Linux 将它整合在了 Linux 内核中。所以，可以在 <code>/proc/config.gz</code> 找到。</li></ul><blockquote><p>💡 如果两者都有，建议使用 <code>/proc/config.gz</code>。这是因为它在只读文件系统中，所以是未被篡改的。</p></blockquote><p>进入含有已经解压出的 Tar 文件的目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd linux-*/</span></span></code></pre></div><p>接着，复制你的 Linux 发行版的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### Debian 和 Fedora 及其衍生版：</span></span>
<span class="line"><span>$ cp /boot/config-&quot;$(uname -r)&quot; .config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Arch Linux 及其衍生版：</span></span>
<span class="line"><span>$ zcat /proc/config.gz &gt; .config</span></span></code></pre></div><h5 id="更新配置文件" tabindex="-1">更新配置文件 <a class="header-anchor" href="#更新配置文件" aria-label="Permalink to “更新配置文件”">​</a></h5><p>一旦完成这些步骤，接下来就需要“更新”配置文件了。因为你的发行版提供的配置很可能比你正在构建的 Linux 内核版本要旧。</p><blockquote><p>💡 <strong>这同样适用于像 Arch Linux 和 Fedora 这样前沿的 Linux 发行版。</strong> 它们并不会因为有新版本可用就立刻发布更新。他们会进行一些质量控制工作，这必然会花费些时间。因此，即便是你的发行版提供的最新内核，相较于你在 kernel.org 上获取的版本也会滞后几个小版本。</p></blockquote><p>要更新一个已有的 <code>.config</code> 文件，我们使用 <code>make</code> 命令搭配 <code>olddefconfig</code> 参数。简单解释一下，这个命令的意思是使用 <em>旧的、默认的、配置</em>。</p><p>这将使用“旧的配置文件”（当前保存为 <code>.config</code>，这是你发行版配置的一份直接副本），并检查从上一版本以来 Linux 代码库中新加的任何配置选项。如果找到任何新的、<em>未配置</em> 的选项，该选项的默认配置值会被使用，并会对 <code>.config</code> 文件进行更新。</p><p>原来的 <code>.config</code> 文件将被重命名为 <code>.config.old</code> 进行备份，并将新的更改写入至 <code>.config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>make olddefconfig</span></span></code></pre></div><p>以下是我机器上的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file .config</span></span>
<span class="line"><span>.config: Linux make config build file, ASCII text</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ make olddefconfig</span></span>
<span class="line"><span>    HOSTCC  scripts/basic/fixdep</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/conf.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/confdata.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/expr.o</span></span>
<span class="line"><span>    LEX     scripts/kconfig/lexer.lex.c</span></span>
<span class="line"><span>    YACC    scripts/kconfig/parser.tab.[ch]</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lexer.lex.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/menu.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/parser.tab.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/preprocess.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/symbol.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/util.o</span></span>
<span class="line"><span>    HOSTLD  scripts/kconfig/conf</span></span>
<span class="line"><span>.config:8593:warning: symbol value &#39;m&#39; invalid for USB_FOTG210_HCD</span></span>
<span class="line"><span>.config:8859:warning: symbol value &#39;m&#39; invalid for USB_FOTG210_UDC</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># configuration written to .config</span></span>
<span class="line"><span>#</span></span></code></pre></div><h5 id="针对-debian-及其衍生版用户" tabindex="-1">针对 Debian 及其衍生版用户 <a class="header-anchor" href="#针对-debian-及其衍生版用户" aria-label="Permalink to “针对 Debian 及其衍生版用户”">​</a></h5><p>Debian 及其衍生版为内核模块使用一个签名证书。默认情况下，你的计算机并不包含这个证书。</p><p>我推荐关闭启用模块签名的选项。具体如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./scripts/config --file .config --set-str SYSTEM_TRUSTED_KEYS &#39;&#39;</span></span>
<span class="line"><span>./scripts/config --file .config --set-str SYSTEM_REVOCATION_KEYS &#39;&#39;</span></span></code></pre></div><p><strong>如果你不这么做，在后面你进行 Linux 内核构建时，可能会导致构建失败。要注意这点。</strong></p><h4 id="使用自定义配置" tabindex="-1">使用自定义配置 <a class="header-anchor" href="#使用自定义配置" aria-label="Permalink to “使用自定义配置”">​</a></h4><p>如果你出于学习内核开发的目的学习如何构建 Linux 内核，那你应该这样做。</p><blockquote><p>🚧 <strong>请注意，偏离你的 Linux 发行版的配置可能无法在实体硬件上“正常”工作。</strong> 问题可能是特定硬件无法工作、Linux 内核无法启动等。</p><p>因此，我们只建议在虚拟机中使用。</p></blockquote>`,54)),a("p",null,[s[28]||(s[28]=n("你可以通过查看 ",-1)),e(i,{href:"https://www.kernel.org/doc/makehelp.txt"},{default:l(()=>[...s[27]||(s[27]=[n("make help 的输出",-1)])]),_:1}),s[29]||(s[29]=n(" 来查看 ",-1)),s[30]||(s[30]=a("em",null,"所有",-1)),s[31]||(s[31]=n(" 可用的选项，但我们主要关注三个 ",-1)),s[32]||(s[32]=a("code",null,"make",-1)),s[33]||(s[33]=n(" 目标：",-1))]),s[63]||(s[63]=p(`<ul><li><code>defconfig</code>: 默认配置。</li><li><code>allmodconfig</code>: 根据当前系统状态，尽可能地把项目构建为可加载模块（而非内建）。</li><li><code>tinyconfig</code>: 极简的 Linux 内核。</li></ul><p>由于 <code>tinyconfig</code> 目标只会构建少数项目，构建时间将会缩短。我个人选择它的原因主要有：</p><ol><li>检查我在代码/工具链中做的修改是否正确，以及代码是否可以编译。</li><li>在虚拟机中只进行少数选项的测试。</li></ol><blockquote><p>🚧 在为 ARM 或 RISC-V 机器构建 Linux 内核时，你可能需要 DTB（设备树的二进制文件）。<strong>使用 <code>tinyconfig</code> 目标将不会启用构建 DTB 的选项，你的内核很可能无法启动。</strong></p><p>当然，你可以用 QEMU 在没有任何 DTB 的情况下启动 Linux 内核。但这篇文章并不会聚焦在此。或许你可以通过评论，让我在之后的时间里覆盖这个话题 😉</p></blockquote><p><strong>除非你确切地知道自己在做什么，否则你应当使用 <code>defconfig</code> 目标。</strong> 以下是我在我的电脑上运行的效果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make defconfig</span></span>
<span class="line"><span>    HOSTCC  scripts/basic/fixdep</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/conf.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/confdata.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/expr.o</span></span>
<span class="line"><span>    LEX     scripts/kconfig/lexer.lex.c</span></span>
<span class="line"><span>    YACC    scripts/kconfig/parser.tab.[ch]</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lexer.lex.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/menu.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/parser.tab.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/preprocess.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/symbol.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/util.o</span></span>
<span class="line"><span>    HOSTLD  scripts/kconfig/conf</span></span>
<span class="line"><span>*** Default configuration is based on &#39;defconfig&#39;</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># configuration written to .config</span></span>
<span class="line"><span>#</span></span></code></pre></div><h4 id="修改配置" tabindex="-1">修改配置 <a class="header-anchor" href="#修改配置" aria-label="Permalink to “修改配置”">​</a></h4><p>无论你是使用 Linux 发行版的配置并更新它，还是使用 <code>defconfig</code> 目标创建新的 <code>.config</code> 文件，你都可能希望熟悉如何修改这个配置文件。<strong>最可靠的修改方式是使用 <code>menuconfig</code> 或 <code>nconfig</code> 目标。</strong></p><p>这两个目标的功能是相同的，只不过提供给你的界面有所不同。这是这两者间唯一的区别。我个人更偏向于使用 <code>menuconfig</code> 目标，但近来我发现 <code>nconfig</code> 在搜索选项时似乎更具直观性，所以我逐渐转向使用它。</p><p>首先，带着 <code>menuconfig</code> 目标运行 <code>make</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make menuconfig</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/mconf.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/checklist.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/inputbox.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/menubox.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/textbox.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/util.o</span></span>
<span class="line"><span>    HOSTCC  scripts/kconfig/lxdialog/yesno.o</span></span>
<span class="line"><span>    HOSTLD  scripts/kconfig/mconf</span></span></code></pre></div><p>在此界面，你可以根据各选项的类型来进行切换操作。</p><p>有两类可切换选项：</p><ul><li>布尔状态选项：这类选项只能关闭（<code>[ ]</code>）或作为内建组件开启（<code>[*]</code>）。</li><li>三态选项：这类选项可以关闭（<code>&lt; &gt;</code>）、内建（<code>&lt;*&gt;</code>），或作为可加载模块（<code>&lt;M&gt;</code>）进行构建。</li></ul><p>想要了解更多关于某个选项的信息，使用上/下箭头键导航至该选项，然后按 <code>&lt;TAB&gt;</code> 键，直至底部的 <code>&lt; Help &gt;</code> 选项被选中，然后按回车键进行选择。此时就会显示关于该配置选项的帮助信息。</p><p><strong>在修改选项时请务必谨慎。</strong></p><p>当你满意配置后，按 <code>&lt;TAB&gt;</code> 键直到底部的 <code>&lt; Save &gt;</code> 选项被选中。然后按回车键进行选择。然后再次按回车键（<strong>记住，此时不要更改文件名</strong>），就能将更新后的配置保存到 <code>.config</code> 文件中。</p><h3 id="构建-linux-内核" tabindex="-1">构建 Linux 内核 <a class="header-anchor" href="#构建-linux-内核" aria-label="Permalink to “构建 Linux 内核”">​</a></h3><p>构建 Linux 内核实际上十分简单。然而，在开始构建之前，让我们为自定义内核构建添加一个标签。我将使用字符串 <code>-pratham</code> 作为标签，并利用 <code>LOCALVERSION</code> 变量来实施。你可以使用以下命令实现配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./scripts/config --file .config --set-str LOCALVERSION &quot;-pratham&quot;</span></span></code></pre></div><p>这一命令将 <code>.config</code> 文件中的 <code>CONFIG_LOCALVERSION</code> 配置选项设为我在结尾指定的字符串，即 <code>-pratham</code>。当然，你也不必非得使用我所用的名字哦 😉</p><p><code>LOCALVERSION</code> 选项可用于设置一个“本地”版本，它会被附加到通常的 <code>x.y.z</code> 版本方案之后，并在你运行 <code>uname -r</code> 命令时一并显示。</p><p>由于我正在构建的是 6.5.5 版本内核，而 <code>LOCALVERSION</code> 字符串被设为 <code>-pratham</code>，因此，对我来说，最后的版本名将会是 <code>6.5.5-pratham</code>。这么做的目的是确保我所构建的自定义内核不会与发行版所提供的内核产生冲突。</p><p>接下来，我们来真正地构建内核。可以用以下的命令完成此步骤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>make -j$(nproc) 2&gt;&amp;1 | tee log</span></span></code></pre></div><p><strong>这对大部分（99%）用户来说已经足够了。</strong></p><p>其中的 <code>-j</code> 选项用于指定并行编译任务的数量。而 <code>nproc</code> 命令用于返回可用处理单位（包括线程）的数量。因此，<code>-j$(nproc)</code> 其实意味着“使用我拥有的 CPU 线程数相同数量的并行编译任务”。</p><p><code>2&gt;&amp;1</code> 会将 STDOUT 和 STDIN 重定向到相同的文件描述符，并通过管道传输给 <code>tee</code> 命令，这会将输出存储在一个名为 <code>log</code> 的文件，并且在控制台打印出完全相同的文本。如果你在构建时遇到错误，并希望回顾日志来检查出了什么问题，这将会十分有用。遇到那种情况，你只需要简单执行 <code>grep Error log</code> 命令就能找到线索。</p><h4 id="自定义-make-目标" tabindex="-1">自定义 make 目标 <a class="header-anchor" href="#自定义-make-目标" aria-label="Permalink to “自定义 make 目标”">​</a></h4><p>在 Linux 内核的源文件夹中，<code>make</code> 命令有一些自定义的目标可供执行各种操作。这些主要作为开发者的参考。如果你的唯一目标是安装一个比你当前发行版更新的 Linux 内核，那么你完全可以跳过这部分内容 😉</p><h5 id="构建目标" tabindex="-1">构建目标 <a class="header-anchor" href="#构建目标" aria-label="Permalink to “构建目标”">​</a></h5><p>作为一名开发者，你可能只想构建 Linux 内核，或者只想构建模块，或者只想构建设备树二进制（DTB）。在这种情况下，你可以指定一个构建目标，然后 <code>make</code> 命令只会构建指定的项目，而不会构建其他的。</p><p>以下是一些构建目标：</p><ul><li><code>vmlinux</code>：纯粹的 Linux 内核。</li><li><code>modules</code>：可加载模块。</li><li><code>dtbs</code>：设备树二进制文件（主要用于 ARM 和 RISC-V 架构）。</li><li><code>all</code>：构建所有被标记了星号 <code>*</code> 的项目（从 <code>make help</code> 的输出中可以查看）。</li></ul><p>通常情况下，你并不需要指定构建目标，因为它们都已经在构建列表中。所列出的目标是在你只想要测试某一个构建目标，而不是其他目标时的情况。</p>`,35)),a("p",null,[s[35]||(s[35]=n("依据你的 ",-1)),e(i,{href:"https://itsfoss.com/arm-aarch64-x86_64/"},{default:l(()=>[...s[34]||(s[34]=[n("计算机架构",-1)])]),_:1}),s[36]||(s[36]=n("，构建完成的 Linux 内核镜像（存放在 ",-1)),s[37]||(s[37]=a("code",null,"/boot",-1)),s[38]||(s[38]=n(" 目录）的名称会有所不同。",-1))]),s[64]||(s[64]=p(`<p>对于 <code>x86_64</code>，Linux 内核的默认镜像名称是 <code>bzImage</code>。因此，如果你只需要构建引导所需的 Linux 内核，你可以像下面这样设定 <code>bzImage</code> 为目标：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### 对于 x86_64</span></span>
<span class="line"><span>$ make bzImage</span></span></code></pre></div><p>“那么如何在我的架构上找到用来调用 <code>make</code> 的目标名称呢？”</p><p>有两种方法。要么你可以执行 <code>make help</code> 之后查找在 <code>Architecture specific targets</code> 下，第一个前面带有星号 <code>*</code> 的选项。</p><p>或者，如果你希望自动完成，你可以利用 <code>image_name</code> 目标得到镜像的完全路径（相对路径），选择性地添加 <code>-s</code> 标志来获得有用的输出。</p><p>以下是我拥有的三台电脑的输出，一台是 <code>x86_64</code>，另一台是 <code>AArch64</code>，还有一台是 <code>riscv</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### x86_64</span></span>
<span class="line"><span>$ make -s image_name</span></span>
<span class="line"><span>arch/x86/boot/bzImage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### AArch64</span></span>
<span class="line"><span>$ make -s image_name</span></span>
<span class="line"><span>arch/arm64/boot/Image.gz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### RISC-V</span></span>
<span class="line"><span>$ make -s image_name</span></span>
<span class="line"><span>arch/riscv/boot/Image.gz</span></span></code></pre></div><p>现在，要只构建 Linux 内核镜像，你可以这样进行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>make $(make -s image_name | awk -F &#39;/&#39; &#39;{print $4}&#39;)</span></span></code></pre></div><h5 id="清理目标" tabindex="-1">清理目标 <a class="header-anchor" href="#清理目标" aria-label="Permalink to “清理目标”">​</a></h5><p>如果你需要清理构建产生的文件，你可以用以下的目标来实现你的需求：</p><ul><li><code>clean</code>：除了 <code>.config</code> 文件外，删除几乎所有其他内容。</li><li><code>mrproper</code>：执行了 <code>make clean</code> 的所有操作外，还会删除 <code>.config</code> 文件。</li><li><code>distclean</code>：除了执行 <code>make mrproper</code> 的所有操作外，还会清理任何补丁文件。</li></ul><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>一旦成功编译了 Linux 内核，接下来就是启动安装一些东西的时候了。“<em>一些</em> 东西？” 没错，我们至少构建了两种不同的东西，如果你使用的是 ARM 或 RISC-V 架构，那就有三种。我会在以下内容中详细解释。</p><blockquote><p>🚧 虽然我将告诉你不同的安装方式，尤其是关于如何改变默认安装路径的方法，但<strong>如果你不确定自己在做什么，那么我不建议你这么做！</strong> 请慎重考虑，如果你决定走自定义的路线，那你需要自己负责后果。默认设置之所以存在，是因为它们有其特殊的原因 😉</p></blockquote><h4 id="安装内核模块" tabindex="-1">安装内核模块 <a class="header-anchor" href="#安装内核模块" aria-label="Permalink to “安装内核模块”">​</a></h4><p>Linux 内核有部分在系统启动时并非必需的。这些部分被构建为可加载模块，即在需要时才进行加载和卸载。</p><p>所以，首先需要安装这些模块。这可以通过 <code>modules_install</code> 目标完成。<strong>必须使用 <code>sudo</code></strong>，因为模块会被安装在 <code>/lib/modules/&lt;kernel_release&gt;-&lt;localversion&gt;</code> 这个需要 <code>root</code> 权限的路径下。</p><p>这个过程不仅会安装内核模块，还会对其进行签名，所以可能需要一些时间。好消息是你可以通过之前提到的 <code>-j$(nproc)</code> 选项来并行执行安装任务，这样会快一些。😉</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make modules_install -j$(nproc)</span></span></code></pre></div><blockquote><p><strong>给开发者的提示：</strong> 你可以通过设定 <code>INSTALL_MOD_PATH</code> 变量来指定一个不同的路径存放 Linux 模块，而不用默认的 <code>/lib/modules/&lt;kernel_release&gt;-&lt;localversion&gt;</code>，具体如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   sudo make modules_install INSTALL_MOD_PATH=&lt;path&gt;</span></span></code></pre></div></blockquote><blockquote><p><strong>另一个给开发者的提示：</strong> 你可以使用 <code>INSTALL_MOD_STRIP</code> 变量来决定是否需要剥离模块的调试符号。如果未设定该变量，调试符号<strong>不会被剥离</strong>。当设为 <code>1</code> 时，符号信息将会被使用 <code>--strip-debug</code> 选项剥离，随后该选项会传递给 <code>strip</code>（或者在使用 Clang 的时候传递给 <code>llvm-strip</code>）工具。</p></blockquote><h4 id="可选-安装-linux-内核头文件" tabindex="-1">（可选）安装 Linux 内核头文件 <a class="header-anchor" href="#可选-安装-linux-内核头文件" aria-label="Permalink to “（可选）安装 Linux 内核头文件”">​</a></h4><p>如果你打算使用这个内核来支持树外模块，比如 ZFS 或英伟达 DKMS，或者打算尝试自行编写模块，你可能会需要 Linux 内核提供的头文件。</p><p>可以通过以下方式使用 <code>headers_install</code> 目标来安装 Linux 内核头文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make headers_install</span></span></code></pre></div><p><strong>应使用 <code>sudo</code> 命令</strong>，因为这些头文件会被安装到 <code>/usr</code> 目录。同时还会在 <code>/usr</code> 目录内创建子目录 <code>include/linux</code>，然后将头文件安装到 <code>/usr/include/linux</code> 内。</p><blockquote><p><strong>给开发者的提示：</strong> 通过设定 <code>INSTALL_HDR_PATH</code> 变量，你可以修改 Linux 内核头文件的安装路径。</p></blockquote><h4 id="安装-dtb-只针对-arm-和-risc-v" tabindex="-1">安装 DTB（只针对 ARM 和 RISC-V） <a class="header-anchor" href="#安装-dtb-只针对-arm-和-risc-v" aria-label="Permalink to “安装 DTB（只针对 ARM 和 RISC-V）”">​</a></h4><p><strong>如果你使用的是 x86_64 架构，那么你可以跳过此步骤！</strong></p><p>如果你针对 ARM 或者 RISC-V 构建了内核，那么在运行 <code>make</code> 的过程中，设备树的二进制文件可能已经被编译出来了。你可以通过在 <code>arch/&lt;machine_architecture&gt;/boot/dts</code> 目录查找 <code>.dtb</code> 文件来确认这一点。</p><p>这里提供了一个快速检查的技巧：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### 对于 AArch32</span></span>
<span class="line"><span>$ find arch/arm/boot/dts -name &quot;*.dtb&quot; -type f | head -n 1 &gt; /dev/null &amp;&amp; echo &quot;DTBs for ARM32 were built&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 对于 AArch64</span></span>
<span class="line"><span>$ find arch/arm64/boot/dts -name &quot;*.dtb&quot; -type f | head -n 1 &gt; /dev/null &amp;&amp; echo &quot;DTBs for ARM64 were built&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 对于 RISC-V</span></span>
<span class="line"><span>$ find arch/riscv/boot/dts -name &quot;*.dtb&quot; -type f | head -n 1 &gt; /dev/null &amp;&amp; echo &quot;DTBs for RISC-V were built&quot;</span></span></code></pre></div><p>如果你看到出现 <code>DTBs for &lt;arch&gt; were built</code> 的消息，那么你可以开始安装 DTB。这可以通过 <code>dtbs_install</code> 目标来实现。</p><p><strong>需要使用 <code>sudo</code></strong>，因为它们会被安装在 <code>/boot/dtb-&lt;kernel_release&gt;-&lt;localversion&gt;</code> 中，而这个目录是由 <code>root</code> 所拥有的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make dtbs_install</span></span></code></pre></div><blockquote><p><strong>给开发者的提示：</strong> 就像安装模块一样，你可以使用 <code>INSTALL_DTBS_PATH</code> 变量指定一个自定义的路径来安装设备树二进制文件。</p></blockquote><h4 id="安装-linux-内核" tabindex="-1">安装 Linux 内核 <a class="header-anchor" href="#安装-linux-内核" aria-label="Permalink to “安装 Linux 内核”">​</a></h4><p>最后，我们来安装 Linux 内核本身！这可以通过 <code>install</code> 目标来完成，就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make install</span></span></code></pre></div><p><strong>在这里必须使用 <code>sudo</code></strong>，因为 Linux 内核将被安装在 <code>/boot</code> 目录，而这个目录不允许普通用户写入。</p><blockquote><p>💡 一般来讲，<code>install</code> 目标也会更新引导加载程序，但是如果它没有成功，那可能是不支持你使用的引导加载程序。如果你没有使用 GRUB 作为你的引导加载程序，请一定要阅读你引导加载程序的使用手册 😉</p></blockquote><blockquote><p><strong>给开发者的提示：</strong> 并不奇怪，<code>INSTALL_PATH</code> 变量被用来设定 Linux 内核的安装位置，而非默认的 <code>/boot</code> 目录。</p></blockquote><h4 id="针对-arch-linux-用户的说明" tabindex="-1">针对 Arch Linux 用户的说明 <a class="header-anchor" href="#针对-arch-linux-用户的说明" aria-label="Permalink to “针对 Arch Linux 用户的说明”">​</a></h4><p>如果你尝试执行了 <code>make install</code> 命令，可能已经注意到产生了错误。错误如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo make install</span></span>
<span class="line"><span>    INSTALL /boot</span></span>
<span class="line"><span>Cannot find LILO.</span></span></code></pre></div><p>要在 Arch Linux 上实际完成 Linux 内核的安装，我们需要手动复制 Linux 内核镜像文件。别担心，如果你使用的是 Arch Linux，手动操作应该是家常便饭了。( ͡° ͜ʖ ͡°)</p><p>可以使用以下命令完成这个步骤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo install -Dm644 &quot;$(make -s image_name)&quot; /boot/vmlinuz-&lt;kernel_release&gt;-&lt;localversion&gt;</span></span></code></pre></div><p>因为我编译的是 6.5.5 版本的内核，所以我将会执行下面这条命令，你可以根据你的实际情况进行适当调整：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo install -Dm644 &quot;$(make -s image_name)&quot; /boot/vmlinuz-6.5.5-pratham</span></span></code></pre></div><p>虽然不是必须的，但最好复制一份名为 <code>System.map</code> 的文件。既然你已经在操作了，一并也复制了 <code>.config</code> 文件吧 😉</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp -vf System.map /boot/System.map-&lt;kernel_release&gt;-&lt;localversion&gt;</span></span>
<span class="line"><span>sudo cp -vf .config /boot/config-&lt;kernel_release&gt;-&lt;localversion&gt;</span></span></code></pre></div><h5 id="生成初始-ram-磁盘" tabindex="-1">生成初始 RAM 磁盘 <a class="header-anchor" href="#生成初始-ram-磁盘" aria-label="Permalink to “生成初始 RAM 磁盘”">​</a></h5><p>当你安装 Arch Linux 时，可能已经了解过 <code>mkinitcpio</code> 这个工具。现在，我们将使用它来创建初始的 RAM 磁盘。</p><p>首先，我们需要创建一个预设文件。向 <code>/etc/mkinitcpio.d/linux-&lt;localversion&gt;.preset</code> 文件中添加以下内容，根据实际需要来替换 <code>&lt;kernel_release&gt;</code> 和 <code>&lt;localversion&gt;</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALL_config=&quot;/etc/mkinitcpio.conf&quot;</span></span>
<span class="line"><span>ALL_kver=&quot;/boot/vmlinuz-&lt;kernel_release&gt;-&lt;localversion&gt;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PRESETS=(&#39;default&#39; &#39;fallback&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default_image=&quot;/boot/initramfs-&lt;kernel_release&gt;-&lt;localversion&gt;.img&quot;</span></span>
<span class="line"><span>fallback_options=&quot;-S autodetect&quot;</span></span></code></pre></div><p>配置完成后，执行下面的命令来生成初始 RAM 磁盘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkinitcpio -p linux-&lt;localversion&gt;</span></span></code></pre></div><p>我自己的电脑上得到的输出如下，你的结果应该会类似！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkinitcpio -p linux-pratham</span></span>
<span class="line"><span>==&gt; Building image from preset: /etc/mkinitcpio.d/linux-pratham.preset: &#39;default&#39;</span></span>
<span class="line"><span>==&gt; Using configuration file: &#39;/etc/mkinitcpio.conf&#39;</span></span>
<span class="line"><span>    -&gt; -k /boot/vmlinuz-6.5.5-pratham -c /etc/mkinitcpio.conf -g /boot/initramfs-6.5.5-pratham.img</span></span>
<span class="line"><span>==&gt; Starting build: &#39;6.5.5-pratham&#39;</span></span>
<span class="line"><span>    -&gt; Running build hook: [base]</span></span>
<span class="line"><span>    -&gt; Running build hook: [udev]</span></span>
<span class="line"><span>    -&gt; Running build hook: [autodetect]</span></span>
<span class="line"><span>    -&gt; Running build hook: [modconf]</span></span>
<span class="line"><span>    -&gt; Running build hook: [kms]</span></span>
<span class="line"><span>    -&gt; Running build hook: [keyboard]</span></span>
<span class="line"><span>==&gt; WARNING: Possibly missing firmware for module: &#39;xhci_pci&#39;</span></span>
<span class="line"><span>    -&gt; Running build hook: [keymap]</span></span>
<span class="line"><span>    -&gt; Running build hook: [consolefont]</span></span>
<span class="line"><span>==&gt; WARNING: consolefont: no font found in configuration</span></span>
<span class="line"><span>    -&gt; Running build hook: [block]</span></span>
<span class="line"><span>    -&gt; Running build hook: [filesystems]</span></span>
<span class="line"><span>    -&gt; Running build hook: [fsck]</span></span>
<span class="line"><span>==&gt; Generating module dependencies</span></span>
<span class="line"><span>==&gt; Creating zstd-compressed initcpio image: &#39;/boot/initramfs-6.5.5-pratham.img&#39;</span></span>
<span class="line"><span>==&gt; Image generation successful</span></span>
<span class="line"><span>==&gt; Building image from preset: /etc/mkinitcpio.d/linux-pratham.preset: &#39;fallback&#39;</span></span>
<span class="line"><span>==&gt; Using configuration file: &#39;/etc/mkinitcpio.conf&#39;</span></span>
<span class="line"><span>==&gt; WARNING: No image or UKI specified. Skipping image &#39;fallback&#39;</span></span></code></pre></div><p>初始 RAM 磁盘已成功生成，现在我们可以进入下一步，更新引导加载器！</p><h5 id="更新-grub" tabindex="-1">更新 GRUB <a class="header-anchor" href="#更新-grub" aria-label="Permalink to “更新 GRUB”">​</a></h5><p>一旦所有必要的文件已成功复制到其对应的位置，接下来，我们将进行 GRUB 的更新。</p><p>使用以下命令对 GRUB 引导加载器进行更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo grub-mkconfig -o /boot/grub/grub.cfg</span></span></code></pre></div><blockquote><p>💡 如果你使用的引导加载器不是 GRUB，请参看 Arch Wiki 中相关的引导加载器文档。</p></blockquote><p><strong>注意，更新 GRUB 并不会直接使新的内核版本设为默认启动选项。在引导时，请在启动菜单中手动选择新的内核版本。</strong></p><p>你可以通过选择 <code>Advanced options for Arch Linux</code> 菜单，并在随后的菜单中选择 <code>Arch Linux, with Linux &lt;kernel_release&gt;-&lt;localversion&gt;</code> 来启用新版的 Linux 内核。</p><h3 id="重启电脑" tabindex="-1">重启电脑 <a class="header-anchor" href="#重启电脑" aria-label="Permalink to “重启电脑”">​</a></h3><p>恭喜你！你已经完成了获取 Linux 内核源代码、进行配置、构建以及安装等所有步骤。现在只需要通过重启电脑并进入新构建和安装的 Linux 内核，就可以开始享受你的努力成果了。</p><p>启动时，请确保从引导加载器中选择正确的 Linux 内核版本。系统启动后，运行 <code>uname -r</code> 命令来确认你正在使用预期的 Linux 内核。</p><p>以下是我自己的电脑输出的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -r</span></span>
<span class="line"><span>6.5.5-pratham</span></span></code></pre></div><p><strong>是时候开始庆祝了！</strong> 🎉</p><h3 id="卸载操作" tabindex="-1">卸载操作 <a class="header-anchor" href="#卸载操作" aria-label="Permalink to “卸载操作”">​</a></h3><blockquote><p>🚧 提示：在删除当前正在使用的内核版本之前，你应该首先切换至较旧的内核版本。</p></blockquote><p>可能你的 Linux 发行版所使用的 Linux 内核版本就是你手动编译的版本，或者你自行编译了新的内核并注意到应卸载旧的内核以节省空间，于是你开始想如何才能卸载。当然，虽然我们无法简单地运行 <code>make uninstall</code> 命令，但这并不代表没有其他的方法！</p><p>我们清楚各个文件的安装位置，因此删除它们相对简单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### 删除内核模块</span></span>
<span class="line"><span>$ rm -rf /lib/modules/&lt;kernel_release&gt;-&lt;localversion&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 删除设备树二进制文件</span></span>
<span class="line"><span>$ rm -rf /boot/dtb-&lt;kernel_release&gt;-&lt;localversion&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 删除 Linux 内核本身</span></span>
<span class="line"><span>$ rm -vf /boot/{config,System,vmlinuz}-&lt;kernel_release&gt;-&lt;localversion&gt;</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这个过程不是一次简单的旅程，是吧？但是现在，我们终于抵达了终点。我们一起学习了手动编译 Linux 内核的全过程，包括安装依赖、获取和验证源码、解压源码、配置 Linux 内核、构建内核以及安装内核。</p><p>如果你喜欢这个详细的步骤指南，请给我留言反馈。如果在操作过程中遇到问题，也欢迎提出，让我知道！</p><p><em>（题图：MJ/853481c5-87e3-42aa-8ace-e9ddfa232f75）</em></p><hr>`,85)),a("p",null,[s[40]||(s[40]=n("via: ",-1)),e(i,{href:"https://itsfoss.com/compile-linux-kernel/"},{default:l(()=>[...s[39]||(s[39]=[n("https://itsfoss.com/compile-linux-kernel/",-1)])]),_:1})]),a("p",null,[s[45]||(s[45]=n("作者：",-1)),e(i,{href:"https://itsfoss.com/author/pratham/"},{default:l(()=>[...s[41]||(s[41]=[n("Pratham Patel",-1)])]),_:1}),s[46]||(s[46]=n(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[42]||(s[42]=[n("lujun9972",-1)])]),_:1}),s[47]||(s[47]=n(" 译者：",-1)),e(i,{href:"https://linux.cn/lctt/ChatGPT"},{default:l(()=>[...s[43]||(s[43]=[n("ChatGPT",-1)])]),_:1}),s[48]||(s[48]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[44]||(s[44]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[51]||(s[51]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[49]||(s[49]=[n("LCTT",-1)])]),_:1}),s[52]||(s[52]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...s[50]||(s[50]=[n("Linux中国",-1)])]),_:1}),s[53]||(s[53]=n(" 荣誉推出",-1))])])}const L=t(c,[["render",g]]);export{C as __pageData,L as default};
